 open:[
  {id:"ao1",r:"agee",lv:5,mins:8,q:"Present your draft thesis research question and evaluate it with Agee's criteria. How would you improve it?",points:["Focus and specific context (steady-cam)","Answerable with your time, access and data (Richards' three questions)","Not leading, not packed; sub-questions that point to data","Link to theory, and the ethical position of you towards participants"],src:"Agee 2009, pp. 439–445"},
  {id:"ao2",r:"miles",lv:4,mins:6,q:"Which research gap(s) does your proposal address? Write the gap statement following Miles.",points:["Name the type (e.g. empirical, population, methodological)","What prior research has done (2–3 studies per point)","What is missing and why it matters","Your purpose and contribution follow logically"],src:"Miles 2017, pp. 3–8"},
  {id:"ao3",r:"flyv",lv:5,mins:10,q:"An examiner asks: 'You study only one or two places. How can your findings matter beyond them?' Answer using Flyvbjerg and Ndame.",points:["Information-oriented selection: critical (most/least likely), extreme, paradigmatic or maximum variation","Falsification and the force of example","Context-dependent knowledge as valuable in itself","Type of case study (idiographic, hypothesis-generating) and honest limits"],src:"Flyvbjerg 2006; Okoko et al. 2023, ch. 11"},
  {id:"ao4",r:"mcard",lv:5,mins:8,q:"How does your research design build in flexibility (McArdle) without losing rigour, and what is your plan B if access fails?",points:["Alternative cases or methods (e.g. online interviews, documents)","Roles and positionality in the field","Ethics stays fixed: consent, overt research","Bryman: research is messy; document changes and reasons"],src:"McArdle 2022; Bryman 2016, p. 13"},
  {id:"ao5",r:"he24",lv:4,mins:8,q:"Compare how Qiu et al., He et al. and Lin & Kant use social media data. What can such data show, and what can it not?",points:["Qiu: content plus sentiment analysis on Reddit; affective and cognitive dimensions","He: SNA plus interviews to measure networked power","Lin & Kant: scraping plus content analysis plus interviews; context matters","Limits: representativeness, platform bias, text only, online ≠ offline power"],src:"Qiu et al. 2024; He et al. 2024; Lin & Kant 2021"},
  {id:"ao6",r:"pinkm",lv:4,mins:6,q:"Your fieldwork can only last a few weeks. Defend this using Pink & Morgan.",points:["Short-term ≠ quick and dirty: different route to knowing","Intensity of encounters (demonstrations, go-alongs)","Ethnographic-theoretical dialogue during fieldwork (with supervisor)","Re-engagement with recordings and photos afterwards"],src:"Pink & Morgan 2013"}
 ],
 teach:{5:{title:"Lecture 5 · Flexible methodologies and the messiness of research",mins:12,scenes:[
  {type:"point",title:"Plans versus reality",text:["Every proposal looks linear: question, theory, method, data, analysis. Real research does not run like that. Bryman calls it the <b>messiness of social research</b>: false starts, blind alleys and enforced changes, hidden in sanitised publications.","McArdle's answer: do not treat change as failure. Build <b>flexible methodologies</b> into your design from the start."],src:"Bryman 2016, p. 13; McArdle 2022, pp. 620–621"},
  {type:"point",title:"Five things you can flex",text:["McArdle names five: <b>methods</b>, <b>techniques</b>, <b>positionality</b>, <b>roles</b> and the <b>research plan</b>.","Her Dublin cases grew from ten to fourteen; one became central only during the research."],src:"McArdle 2022, p. 620"},
  {type:"check",q:"A key case closes before your fieldwork. What would McArdle do?",o:["Keep the case and reach participants online (social media, online interview)","Drop the case immediately","Fake the data","Postpone the whole thesis"],a:0,e:"That is what she did with The Barricade Inn.",src:"pp. 623–624"},
  {type:"classmate",who:"L",name:"Lotte",say:"So flexibility means I don't need a detailed plan for my proposal.",ask:"Is Lotte right?",o:["No: plans remain valuable and start the thinking; you hold them flexibly and keep ethics fixed","Yes: plans are pointless","Yes, but only for PhDs","No: plans must never change"],a:0,e:"McArdle explicitly keeps GANTT charts and plans, and still followed ethics protocols such as online consent.",src:"pp. 623, 625"},
  {type:"point",title:"Roles in the field",text:["At Apollo House McArdle was volunteer, activist and researcher at once. Not everyone knew she was researching: 'a clumsy, blurry line of participant observation'.","Flexibility in roles gives insider insight, but raises ethical questions you must reflect on."],src:"p. 624"},
  {type:"point",title:"Theory and methods: the link",text:["The theory you choose should follow from what you want to find out (MacCallum et al., ch. 3 note). Agee adds that theory and questions evolve together.","In your oral, show that line: question → theory → method → data → analysis, and where you would adapt."],src:"MacCallum et al. 2019, p. 6; Agee 2009, pp. 437–439"},
  {type:"check",q:"Which pair best describes the relation between theory and research questions in Agee (2009)?",o:["Dialogic: theory shapes questions, and data can lead to new theory and new questions","Theory comes only after analysis","Questions never relate to theory","Theory is fixed before the study and never changes"],a:0,e:"Karpiak's turn to chaos theory during data collection.",src:"Agee 2009, pp. 437–439"}]}}
